static const char __pyx_k_Canvas_instructions_added_in_kv[] = "Canvas instructions added in kv must be declared before child widgets.";
static const char __pyx_k_Unbind_all_the_handlers_created[] = "Unbind all the handlers created by the KV rules of the\n        widget. The :attr:`kivy.uix.widget.Widget.uid` is passed here\n        instead of the widget itself, because Builder is using it in the\n        widget destructor.\n\n        This effectively clears all the KV rules associated with this widget.\n        For example:\n\n        .. code-block:: python\n\n            >>> w = Builder.load_string('''\n            ... Widget:\n            ...     height: self.width / 2. if self.disabled else self.width\n            ...     x: self.y + 50\n            ... ''')\n            >>> w.size\n            [100, 100]\n            >>> w.pos\n            [50, 0]\n            >>> w.width = 500\n            >>> w.size\n            [500, 500]\n            >>> Builder.unbind_widget(w.uid)\n            >>> w.width = 222\n            >>> w.y = 500\n            >>> w.size\n            [222, 500]\n            >>> w.pos\n            [50, 500]\n\n        .. versionadded:: 1.7.2\n        ";
static const char __pyx_k_BuilderBase_unbind_property_line[] = "BuilderBase.unbind_property (line 860)";
